public class RunOrig {
    static class L extends BaseErrorListener {
        int errors = 0;
        @Override
        public void syntaxError(Recognizer<?, ?> r, Object o, int line, int col,
                                String msg, RecognitionException e) {
            errors++;
        }
    }

    public static void main(String[] args) throws Exception {
        L err = new L();
        for (String path : args) {
            String src = new String(Files.readAllBytes(Paths.get(path)), "UTF-8");
            System.out.println("=== " + path);
            try {
                Lexer lexer = new Lexer(CharStreams.fromString(src));
                lexer.removeErrorListeners();
                lexer.addErrorListener(err);
                CommonTokenStream tokens = new CommonTokenStream(lexer);
                tokens.fill();
