+## 2. 写 `compiler/src/ast/ast.h`（AST 的数据结构）
+
+```cpp
+#pragma once
+
+#include <memory>
+#include <string>
+#include <vector>
+
+namespace rx {
+
+struct Loc {
+    size_t line = 0;
+    size_t col = 0;
+};
+
+// ---------- 类型 ----------
+struct Type;
+using TypePtr = std::unique_ptr<Type>;
+
+struct Type {
+    enum Kind { BUILTIN, STRUCT, BOX, VEC, REF, ARRAY, UNIT } kind = UNIT;
+    std::string name;       // BUILTIN: i32/u32/isize/usize/bool; STRUCT: 结构体名/Self
+    TypePtr elem;           // BOX/VEC/REF/ARRAY 的元素类型
+    bool isMut = false;     // REF 是否是 &mut
+    std::string arrayLen;   // ARRAY 的长度源码文本（语义阶段再求值）
+};
+
+// ---------- 常量值（数组长度、const 项） ----------
+struct ConstVal;
+using ConstValPtr = std::unique_ptr<ConstVal>;
+
+struct ConstVal {
+    enum Kind { INT, BOOL, PATH, NEG } kind = INT;
+    std::string text;        // INT/BOOL/PATH 的原文
+    ConstValPtr inner;       // NEG 的内层
+};
+
+// ---------- 表达式 / 语句 / 块 / 项 ----------
+struct Expr;
+using ExprPtr = std::unique_ptr<Expr>;
+struct Stmt;
+using StmtPtr = std::unique_ptr<Stmt>;
+struct Block;
+using BlockPtr = std::unique_ptr<Block>;
+struct Item;
+using ItemPtr = std::unique_ptr<Item>;
+
+struct PathSegment {
+    std::string name;                 // Vec / new / x 段名
+    std::vector<TypePtr> typeArgs;    // Vec::<i32> 中的 [i32]
+};
+
+struct StructFieldInit {
+    std::string name;
+    ExprPtr value;
+};
+
+struct Expr {
+    enum Kind {
+        INT_LIT, BOOL_LIT, PATH, UNIT,
+        UNARY, BINARY, ASSIGN,
+        CALL, METHOD_CALL, FIELD, INDEX,
+        ARRAY, REPEAT_ARRAY, STRUCT_INIT, CAST, REF, DEREF,
+        BLOCK, IF, WHILE, LOOP, BREAK, CONTINUE, RETURN,
+        UNKNOWN
+    } kind = UNKNOWN;
+    Loc loc;
+
+    std::string op;                        // 运算符 / 方法名 / 字段名 / 字面量原文
+    std::vector<ExprPtr> kids;             // 含义见下
+    std::vector<PathSegment> path;         // PATH / STRUCT_INIT 的路径
+    TypePtr type;                          // CAST 的目标类型
+    std::vector<StructFieldInit> fields;   // STRUCT_INIT 字段
+    ConstValPtr count;                     // REPEAT_ARRAY 的长度
+    BlockPtr block;                        // BLOCK 的语句序列
+
+    // UNARY/REF/DEREF/BREAK/RETURN: kids = {操作数或返回值, 可空}
+    // BINARY/ASSIGN:                kids = {左, 右}
+    // CALL:                         kids = {被调用者, 实参...}
+    // METHOD_CALL:                  kids = {接收者, 实参...}; op = 方法名
+    // FIELD:                        kids = {接收者}; op = 字段名
+    // INDEX:                        kids = {接收者, 下标}
+    // ARRAY:                        kids = 各元素
+    // REPEAT_ARRAY:                 kids = {元素}; count 为长度
+    // IF:                           kids = {条件, then 块, else 分支(可空)}
+    // WHILE:                        kids = {条件, 循环体}
+    // LOOP:                         kids = {循环体}
+};
+
+struct Stmt {
+    enum Kind { LET, EXPR } kind = EXPR;
+    Loc loc;
+    std::string name;    // LET
+    bool isMut = false;  // LET
+    TypePtr type;        // LET 的类型标注（可空）
+    ExprPtr expr;        // LET 初始化式 / EXPR 表达式
+};
+
+struct Block {
+    Loc loc;
+    std::vector<StmtPtr> stmts;
+    ExprPtr tail;        // 块尾表达式（可空）
+};
+
+struct Param {
+    std::string name;
+    TypePtr type;
+    bool isMut = false;
+};
+
+struct FnDef {
+    std::string name;
+    std::vector<Param> params;
+    TypePtr ret;         // 可空（默认 ()）
+    BlockPtr body;
+};
+
+struct StructFieldDef {
+    std::string name;
+    TypePtr type;
+};
+
+struct StructDef {
+    std::string name;
+    std::vector<StructFieldDef> fields;
+    std::vector<std::string> derives;   // "Copy" / "Clone" / "PartialEq" / "Eq"
+};
+
+struct ConstDef {
+    std::string name;
+    TypePtr type;
+    ConstValPtr value;
+};
+
+struct ImplDef {
+    TypePtr target;
+    std::vector<ItemPtr> items;
+};
+
+struct Item {
+    enum Kind { FN, STRUCT, CONST, IMPL } kind = FN;
+    Loc loc;
+    std::string name;    // FN/STRUCT/CONST
+    FnDef fn;
+    StructDef structDef;
+    ConstDef constDef;
+    ImplDef impl;
+};
+
+struct Crate {
+    std::vector<ItemPtr> items;
+};
+
+std::string dumpCrate(const Crate& crate);
+
+}  // namespace rx
+```
