}

std::string textOf(const tree::ParseTree* node) { return node->getText(); }

const tree::ParseTree* oneChildOfRule(const tree::ParseTree* node, size_t rule) {
    for (auto* c : node->children) if (isRule(c, rule)) return c;
    return nullptr;
}

std::vector<const tree::ParseTree*> childrenOfRule(const tree::ParseTree* node, size_t rule) {
    std::vector<const tree::ParseTree*> out;
    for (auto* c : node->children) if (isRule(c, rule)) out.push_back(c);
    return out;
