    return nullptr;
}
std::vector<ParseTree*> childrenOfRule(const ParseTree* node, size_t rule) {
    std::vector<ParseTree*> out;
    for (auto* c : node->children)
        if (isRule(c, rule)) out.push_back(c);
    return out;
}
bool hasTerminal(const ParseTree* node, const std::string& text) {
    for (auto* c : node->children)
        if (isTerminal(c) && c->getText() == text) return true;
    return false;
}

ExprPtr buildExpr(const ParseTree* node);
TypePtr buildType(const ParseTree* node);
BlockPtr buildBlock(const ParseTree* node);
StmtPtr buildStmt(const ParseTree* node);

TypePtr makeType(Type::Kind kind) {
    auto t = std::make_unique<Type>();
    t->kind = kind;
    return t;
}
TypePtr makeNamedType(const std::string& name, const std::vector<TypePtr>& args) {
    if (name == "Box" && args.size() == 1) {
        auto t = makeType(Type::BOX);
        t->elem = cloneType(args[0]);
        return t;
    }
    if (name == "Vec" && args.size() == 1) {
        auto t = makeType(Type::VEC);
        t->elem = cloneType(args[0]);
        return t;
    }
    if (name == "i32" || name == "u32" || name == "isize" || name == "usize" ||
        name == "bool") {
        auto t = makeType(Type::BUILTIN);
        t->name = name;
        return t;
    }
    auto t = makeType(Type::STRUCT);
    t->name = name;
    return t;
}

const std::string& BUILTIN_NAMES();

bool isOperatorRule(size_t rule) {
    return rule == P::RuleAssignmentOperator || rule == P::RuleComparisonExceptLt ||
           rule == P::RuleShiftRight || rule == P::RuleEqualsSign ||
           rule == P::RuleAdditiveOperator || rule == P::RuleMultiplicativeOperator;
}

bool isAssignOp(const std::string& op) {
    return op == "=" || op == "+=" || op == "-=" || op == "*=" || op == "/=" ||
           op == "%=" || op == "&=" || op == "|=" || op == "^=" || op == "<<=" ||
           op == ">>=";
}

bool isBinaryOpText(const std::string& t) {
    static const char* ops[] = {
        "+", "-", "*", "/", "%", "&", "|", "^", "<<", ">>", "==", "!=",
        "<", "<=", ">", ">=", "&&", "||", "=", "+=", "-=", "*=", "/=", "%=",
        "&=", "|=", "^=", "<<=", ">>="};
    for (auto* op : ops)
        if (t == op) return true;
    return false;
}

ExprPtr unknownExpr(const ParseTree* node) {
    auto e = std::make_unique<Expr>();
    e->kind = Expr::UNKNOWN;
    e->op = node->getText();
    return e;
}

std::vector<TypePtr> buildTypeArgs(const ParseTree* genericArgs) {
    std::vector<TypePtr> out;
    for (auto* arg : childrenOfRule(genericArgs, P::RuleGenericArg)) {
        for (auto* c : arg->children)
            if (isRule(c, P::RuleTypeRef)) out.push_back(buildType(c));
    }
    return out;
}

std::vector<PathSegment> buildPathSegments(const ParseTree* pathInExpr) {
    std::vector<PathSegment> segs;
    for (auto* c : pathInExpr->children) {
        if (!isRule(c, P::RulePathExprSegment)) continue;
        PathSegment seg;
        auto* ident = childOfRule(c, P::RulePathIdentSegment);
        seg.name = ident ? ident->getText() : c->getText();
        if (auto* args = childOfRule(c, P::RuleGenericArgs))
            seg.typeArgs = buildTypeArgs(args);
        segs.push_back(std::move(seg));
    }
    if (segs.empty()) {
        PathSegment seg;
        seg.name = pathInExpr->getText();
        segs.push_back(std::move(seg));
    }
    return segs;
}

TypePtr buildType(const ParseTree* node) {
    switch (ruleOf(node)) {
        case P::RuleTypeRef: {
            if (auto* inner = childOfRule(node, P::RuleTypeRef)) return buildType(inner);
            if (hasTerminal(node, "(") && hasTerminal(node, ")")) return makeType(Type::UNIT);
            for (auto* c : node->children)
                if (!isTerminal(c)) return buildType(c);
            return makeType(Type::UNIT);
        }
        case P::RuleReferenceType:
        case P::RuleClosedCastType: {
            size_t rule = ruleOf(node);
            int refs = 0;
            bool mut = false;
            const ParseTree* inner = nullptr;
            std::string name;
            TypePtr result;

            for (auto* c : node->children) {
                if (isTerminal(c)) {
                    std::string t = c->getText();
                    if (t == "&") ++refs;
                    else if (t == "&&") refs += 2;
                    else if (t == "mut") mut = true;
                } else if (isRule(c, P::RuleTypeRef) || isRule(c, P::RuleClosedCastType)) {
                    inner = c;
                } else if (isRule(c, P::RuleArrayType)) {
                    return buildType(c);
                } else if (isRule(c, P::RulePathIdentSegment)) {
                    name = c->getText();
                }
            }
            if (refs > 0 && inner) {
                result = buildType(inner);
                if (refs == 2) {
                    auto innerRef = makeType(Type::REF);
                    innerRef->isMut = mut;
                    innerRef->elem = std::move(result);
                    auto outerRef = makeType(Type::REF);
                    outerRef->elem = std::move(innerRef);
                    return outerRef;
                }
                auto ref = makeType(Type::REF);
                ref->isMut = mut;
                ref->elem = std::move(result);
                return ref;
            }
            if (rule == P::RuleClosedCastType && !name.empty()) {
                std::vector<TypePtr> args;
                if (auto* ga = childOfRule(node, P::RuleGenericArgs))
                    args = buildTypeArgs(ga);
                return makeNamedType(name, args);
            }
            return makeType(Type::UNIT);
        }
        case P::RuleArrayType: {
            auto t = makeType(Type::ARRAY);
            if (auto* elem = childOfRule(node, P::RuleTypeRef)) t->elem = buildType(elem);
            if (auto* len = childOfRule(node, P::RuleConstValue)) t->arrayLen = len->getText();
            return t;
        }
        case P::RuleTypePath: {
            std::string name;
            std::vector<TypePtr> args;
            for (auto* seg : childrenOfRule(node, P::RuleTypePathSegment)) {
                if (auto* ident = childOfRule(seg, P::RulePathIdentSegment)) name = ident->getText();
                if (auto* ga = childOfRule(seg, P::RuleGenericArgs)) args = buildTypeArgs(ga);
            }
            if (name.empty()) name = node->getText();
            return makeNamedType(name, args);
        }
        default:
            break;
    }
    auto t = makeType(Type::STRUCT);
    t->name = node->getText();
    return t;
}

ConstValPtr buildConstVal(const ParseTree* node) {
    if (isRule(node, P::RuleConstValue)) {
        if (auto* inner = childOfRule(node, P::RuleConstValue)) return buildConstVal(inner);
        if (auto* mag = childOfRule(node, P::RuleMagnitude)) {
            auto v = std::make_unique<ConstVal>();
            v->kind = ConstVal::NEG;
            v->inner = buildConstVal(mag);
            v->text = node->getText();
            return v;
        }
        if (auto* path = childOfRule(node, P::RulePathInExpression)) {
            auto v = std::make_unique<ConstVal>();
            v->kind = ConstVal::PATH;
            v->text = path->getText();
            return v;
        }
    }
    if (isRule(node, P::RuleMagnitude)) {
        if (auto* inner = childOfRule(node, P::RuleMagnitude)) return buildConstVal(inner);
        if (auto* path = childOfRule(node, P::RulePathInExpression)) {
            auto v = std::make_unique<ConstVal>();
            v->kind = ConstVal::PATH;
            v->text = path->getText();
            return v;
        }
    }
    auto v = std::make_unique<ConstVal>();
    v->text = node->getText();
    v->kind = (v->text == "true" || v->text == "false") ? ConstVal::BOOL : ConstVal::INT;
    return v;
}

ExprPtr makeLiteral(const ParseTree* node) {
    auto e = std::make_unique<Expr>();
    e->op = node->getText();
    e->kind = (e->op == "true" || e->op == "false") ? Expr::BOOL_LIT : Expr::INT_LIT;
    return e;
}

ExprPtr makeUnary(const std::string& op, ExprPtr operand) {
    if (op == "*") {
        auto e = std::make_unique<Expr>();
        e->kind = Expr::DEREF;
        e->kids.push_back(std::move(operand));
        return e;
    }
    if (!op.empty() && op[0] == '&') {
        bool mut = op.find("mut") != std::string::npos;
        int count = (op.size() > 1 && op[1] == '&') ? 2 : 1;
        ExprPtr result = std::move(operand);
        for (int i = 0; i < count; ++i) {
            auto e = std::make_unique<Expr>();
            e->kind = Expr::REF;
            e->op = mut && i == 0 ? "mut" : "";
            e->kids.push_back(std::move(result));
            result = std::move(e);
        }
        return result;
    }
    auto e = std::make_unique<Expr>();
    e->kind = Expr::UNARY;
    e->op = op;
    e->kids.push_back(std::move(operand));
    return e;
}

ExprPtr applySuffix(ExprPtr recv, const ParseTree* suffix) {
    if (auto* args = childOfRule(suffix, P::RuleCallArguments)) {
        auto e = std::make_unique<Expr>();
        e->kind = Expr::CALL;
        e->kids.push_back(std::move(recv));
        for (auto* a : childrenOfRule(args, P::RuleExpression))
            e->kids.push_back(buildExpr(a));
        return e;
    }
    if (auto* dot = childOfRule(suffix, P::RuleDotSuffix)) {
        if (auto* callArgs = childOfRule(dot, P::RuleCallArguments)) {
            auto e = std::make_unique<Expr>();
            e->kind = Expr::METHOD_CALL;
            auto* seg = childOfRule(dot, P::RulePathExprSegment);
            auto* ident = seg ? childOfRule(seg, P::RulePathIdentSegment) : nullptr;
            e->op = ident ? ident->getText() : (seg ? seg->getText() : "");
            e->kids.push_back(std::move(recv));
            for (auto* a : childrenOfRule(callArgs, P::RuleExpression))
                e->kids.push_back(buildExpr(a));
            return e;
        }
        auto e = std::make_unique<Expr>();
        e->kind = Expr::FIELD;
        auto* ident = childOfRule(dot, P::RuleIdentifier);
        e->op = ident ? ident->getText() : "";
        e->kids.push_back(std::move(recv));
        return e;
    }
    auto e = std::make_unique<Expr>();
    e->kind = Expr::INDEX;
    e->kids.push_back(std::move(recv));
    e->kids.push_back(buildExpr(childOfRule(suffix, P::RuleExpression)));
    return e;
}

ExprPtr buildChain(const ParseTree* node) {
    ExprPtr current;
    std::string pendingOp;
    bool pendingCast = false;
    std::vector<const ParseTree*> suffixes;

    for (auto* child : node->children) {
        if (isTerminal(child)) {
            std::string t = child->getText();
            if (t == "as") pendingCast = true;
            else if (isBinaryOpText(t)) pendingOp = t;
            continue;
        }
        size_t rule = ruleOf(child);
        if (isOperatorRule(rule)) {
            pendingOp = child->getText();
            continue;
        }
        if (rule == P::RulePostfixSuffix) {
            suffixes.push_back(child);
            continue;
        }
        if (pendingCast) {
            auto cast = std::make_unique<Expr>();
            cast->kind = Expr::CAST;
            cast->type = buildType(child);
            cast->kids.push_back(std::move(current));
            current = std::move(cast);
            pendingCast = false;
            continue;
        }
        ExprPtr operand = buildExpr(child);
        if (!operand) continue;
        if (!current) {
            current = pendingOp.empty() ? std::move(operand)
                                        : makeUnary(pendingOp, std::move(operand));
            pendingOp.clear();
        } else if (!pendingOp.empty()) {
            auto e = std::make_unique<Expr>();
            e->kind = isAssignOp(pendingOp) ? Expr::ASSIGN : Expr::BINARY;
            e->op = pendingOp;
            e->kids.push_back(std::move(current));
            e->kids.push_back(std::move(operand));
            current = std::move(e);
            pendingOp.clear();
        } else {
            current = unknownExpr(node);
        }
    }
    for (auto* suffix : suffixes) current = applySuffix(std::move(current), suffix);
    if (!current) return unknownExpr(node);
    return current;
}

ExprPtr makeBlockExpr(const ParseTree* blockNode) {
    auto e = std::make_unique<Expr>();
    e->kind = Expr::BLOCK;
    e->block = buildBlock(blockNode);
    return e;
}

ExprPtr buildIf(const ParseTree* node) {
    auto e = std::make_unique<Expr>();
    e->kind = Expr::IF;
    e->kids.push_back(buildExpr(childOfRule(node, P::RuleConditionExpression)));
    auto blocks = childrenOfRule(node, P::RuleBlockExpression);
    if (!blocks.empty()) e->kids.push_back(buildBlock(blocks[0]));
    if (hasTerminal(node, "else")) {
        if (auto* elseIf = childOfRule(node, P::RuleIfExpression))
            e->kids.push_back(buildIf(elseIf));
        else if (blocks.size() > 1)
            e->kids.push_back(buildBlock(blocks[1]));
    }
    return e;
}

ExprPtr buildLoop(const ParseTree* node) {
    auto e = std::make_unique<Expr>();
    e->kind = Expr::LOOP;
    e->kids.push_back(makeBlockExpr(childOfRule(node, P::RuleBlockExpression)));
    return e;
}

ExprPtr buildWhile(const ParseTree* node) {
    auto e = std::make_unique<Expr>();
    e->kind = Expr::WHILE;
    e->kids.push_back(buildExpr(childOfRule(node, P::RuleConditionExpression)));
    e->kids.push_back(makeBlockExpr(childOfRule(node, P::RuleBlockExpression)));
    return e;
}

const ParseTree* firstExprOperand(const ParseTree* node) {
    for (auto* c : node->children) {
        size_t r = ruleOf(c);
        if (r == P::RuleExpression || r == P::RuleConditionExpression ||
            r == P::RuleConditionBreakExpression)
            return c;
    }
    return nullptr;
}

ExprPtr buildArray(const ParseTree* node) {
    auto e = std::make_unique<Expr>();
    auto exprs = childrenOfRule(node, P::RuleExpression);
    if (hasTerminal(node, ";")) {
        e->kind = Expr::REPEAT_ARRAY;
        if (!exprs.empty()) e->kids.push_back(buildExpr(exprs[0]));
        e->count = buildConstVal(childOfRule(node, P::RuleConstValue));
    } else {
        e->kind = Expr::ARRAY;
        for (auto* x : exprs) e->kids.push_back(buildExpr(x));
    }
    return e;
}

ExprPtr buildPrimary(const ParseTree* node) {
    if (auto* lit = childOfRule(node, P::RuleLiteralExpression)) return makeLiteral(lit);
    if (auto* path = childOfRule(node, P::RulePathInExpression)) {
        auto e = std::make_unique<Expr>();
        e->path = buildPathSegments(path);
        if (hasTerminal(node, "{")) {
            e->kind = Expr::STRUCT_INIT;
            if (auto* fields = childOfRule(node, P::RuleStructExprFields)) {
                for (auto* f : childrenOfRule(fields, P::RuleStructExprField)) {
                    StructFieldInit fi;
                    auto* id = childOfRule(f, P::RuleIdentifier);
                    fi.name = id ? id->getText() : "";
                    if (auto* v = childOfRule(f, P::RuleExpression))
                        fi.value = buildExpr(v);
                    e->fields.push_back(std::move(fi));
                }
            }
        } else {
            e->kind = Expr::PATH;
            e->op = path->getText();
        }
        return e;
    }
    if (auto* arr = childOfRule(node, P::RuleArrayExpression)) return buildArray(arr);
    if (auto* ewb = childOfRule(node, P::RuleExpressionWithBlock)) {
        if (auto* b = childOfRule(ewb, P::RuleBlockExpression)) return makeBlockExpr(b);
        if (auto* i = childOfRule(ewb, P::RuleIfExpression)) return buildIf(i);
        if (hasTerminal(ewb, "loop")) return buildLoop(ewb);
        if (hasTerminal(ewb, "while")) return buildWhile(ewb);
    }
    if (auto* i = childOfRule(node, P::RuleIfExpression)) return buildIf(i);
    if (hasTerminal(node, "loop")) return buildLoop(node);
    if (hasTerminal(node, "while")) return buildWhile(node);
    if (auto* b = childOfRule(node, P::RuleBlockExpression)) return makeBlockExpr(b);
    if (hasTerminal(node, "break")) {
        auto e = std::make_unique<Expr>();
        e->kind = Expr::BREAK;
        if (auto* v = firstExprOperand(node)) e->kids.push_back(buildExpr(v));
        return e;
    }
    if (hasTerminal(node, "return")) {
        auto e = std::make_unique<Expr>();
        e->kind = Expr::RETURN;
        if (auto* v = firstExprOperand(node)) e->kids.push_back(buildExpr(v));
        return e;
    }
    if (hasTerminal(node, "continue")) {
        auto e = std::make_unique<Expr>();
        e->kind = Expr::CONTINUE;
        return e;
    }
    if (hasTerminal(node, "(")) {
        if (auto* inner = childOfRule(node, P::RuleExpression)) return buildExpr(inner);
        auto e = std::make_unique<Expr>();
        e->kind = Expr::UNIT;
        return e;
    }
    return unknownExpr(node);
}

ExprPtr buildExpr(const ParseTree* node) {
    if (!node) return nullptr;
    switch (ruleOf(node)) {
        case P::RuleLiteralExpression:
            return makeLiteral(node);
        case P::RulePrimaryExpression:
        case P::RuleNonBlockPrimary:
        case P::RuleConditionPrimary:
        case P::RuleConditionPrimaryWithoutBareBlock:
            return buildPrimary(node);
        case P::RuleExpressionWithBlock: {
            if (auto* b = childOfRule(node, P::RuleBlockExpression)) return makeBlockExpr(b);
            if (auto* i = childOfRule(node, P::RuleIfExpression)) return buildIf(i);
            if (hasTerminal(node, "loop")) return buildLoop(node);
            if (hasTerminal(node, "while")) return buildWhile(node);
            return unknownExpr(node);
        }
        case P::RuleBlockExpression:
            return makeBlockExpr(node);
        case P::RuleIfExpression:
            return buildIf(node);
        case P::RuleArrayExpression:
            return buildArray(node);
        default:
            return buildChain(node);
    }
}

StmtPtr buildStmt(const ParseTree* node) {
    if (auto* let = childOfRule(node, P::RuleLetStatement)) {
        auto s = std::make_unique<Stmt>();
        s->kind = Stmt::LET;
        auto* bind = childOfRule(let, P::RuleIdentifierBinding);
        if (bind) {
            s->isMut = hasTerminal(bind, "mut");
            auto* id = childOfRule(bind, P::RuleIdentifier);
            s->name = id ? id->getText() : bind->getText();
        }
        if (auto* t = childOfRule(let, P::RuleTypeRef)) s->type = buildType(t);
        if (auto* e = childOfRule(let, P::RuleExpression)) s->expr = buildExpr(e);
        return s;
    }
    if (auto* ewb = childOfRule(node, P::RuleExpressionWithBlock)) {
        auto s = std::make_unique<Stmt>();
        s->kind = Stmt::EXPR;
        if (auto* b = childOfRule(ewb, P::RuleBlockExpression))
            s->expr = makeBlockExpr(b);
        else if (auto* i = childOfRule(ewb, P::RuleIfExpression))
            s->expr = buildIf(i);
        else if (hasTerminal(ewb, "loop"))
            s->expr = buildLoop(ewb);
        else if (hasTerminal(ewb, "while"))
            s->expr = buildWhile(ewb);
        return s;
    }
    if (auto* se = childOfRule(node, P::RuleStatementExpression)) {
        auto s = std::make_unique<Stmt>();
        s->kind = Stmt::EXPR;
        s->expr = buildExpr(se);
        return s;
    }
    return nullptr;
}

BlockPtr buildBlock(const ParseTree* node) {
    auto b = std::make_unique<Block>();
    for (auto* c : node->children) {
        if (isRule(c, P::RuleStatement)) {
            if (auto s = buildStmt(c)) b->stmts.push_back(std::move(s));
        } else if (isRule(c, P::RuleStatementExpression)) {
            b->tail = buildExpr(c);
        }
    }
    return b;
}

ItemPtr buildFn(const ParseTree* node) {
    auto item = std::make_unique<Item>();
    item->kind = Item::FN;
    if (auto* id = childOfRule(node, P::RuleIdentifier)) item->name = id->getText();
    if (auto* params = childOfRule(node, P::RuleFunctionParameters)) {
        for (auto* c : params->children) {
            if (isRule(c, P::RuleSelfParam)) {
                Param p;
                p.name = "self";
                bool byRef = hasTerminal(c, "&");
                bool mut = hasTerminal(c, "mut");
                auto selfType = makeType(Type::STRUCT);
                selfType->name = "Self";
                if (byRef) {
                    auto ref = makeType(Type::REF);
                    ref->isMut = mut;
                    ref->elem = std::move(selfType);
                    p.type = std::move(ref);
                } else {
                    p.isMut = mut;
                    p.type = std::move(selfType);
                }
                item->fn.params.push_back(std::move(p));
            } else if (isRule(c, P::RuleFunctionParam)) {
                Param p;
                if (auto* bind = childOfRule(c, P::RuleIdentifierBinding)) {
                    p.isMut = hasTerminal(bind, "mut");
                    if (auto* id = childOfRule(bind, P::RuleIdentifier))
                        p.name = id->getText();
                }
                if (auto* t = childOfRule(c, P::RuleTypeRef)) p.type = buildType(t);
                item->fn.params.push_back(std::move(p));
            }
        }
    }
    if (auto* ret = childOfRule(node, P::RuleTypeRef)) item->fn.ret = buildType(ret);
    if (auto* body = childOfRule(node, P::RuleBlockExpression)) item->fn.body = buildBlock(body);
    return item;
}

ItemPtr buildStruct(const ParseTree* node) {
    auto item = std::make_unique<Item>();
    item->kind = Item::STRUCT;
    if (auto* id = childOfRule(node, P::RuleIdentifier)) item->name = id->getText();
    for (auto* attr : childrenOfRule(node, P::RuleOuterAttribute))
        for (auto* d : childrenOfRule(attr, P::RuleDeriveName))
            item->structDef.derives.push_back(d->getText());
    for (auto* f : childrenOfRule(node, P::RuleStructField)) {
        StructFieldDef field;
        if (auto* id = childOfRule(f, P::RuleIdentifier)) field.name = id->getText();
        if (auto* t = childOfRule(f, P::RuleTypeRef)) field.type = buildType(t);
        item->structDef.fields.push_back(std::move(field));
    }
    return item;
}

ItemPtr buildConst(const ParseTree* node) {
    auto item = std::make_unique<Item>();
    item->kind = Item::CONST;
    if (auto* id = childOfRule(node, P::RuleIdentifier)) item->name = id->getText();
    if (auto* t = childOfRule(node, P::RuleTypeRef)) item->constDef.type = buildType(t);
    if (auto* v = childOfRule(node, P::RuleConstValue)) item->constDef.value = buildConstVal(v);
    return item;
}

ItemPtr buildImpl(const ParseTree* node) {
    auto item = std::make_unique<Item>();
    item->kind = Item::IMPL;
    if (auto* t = childOfRule(node, P::RuleTypeRef)) item->impl.target = buildType(t);
    for (auto* a : childrenOfRule(node, P::RuleAssociatedItem)) {
        if (auto* fn = childOfRule(a, P::RuleFunctionDefinition))
            item->impl.items.push_back(buildFn(fn));
        else if (auto* c = childOfRule(a, P::RuleConstantItem))
            item->impl.items.push_back(buildConst(c));
    }
    return item;
}

ItemPtr buildItem(const ParseTree* node) {
    if (auto* fn = childOfRule(node, P::RuleFunctionDefinition)) return buildFn(fn);
    if (auto* s = childOfRule(node, P::RuleStructDefinition)) return buildStruct(s);
    if (auto* c = childOfRule(node, P::RuleConstantItem)) return buildConst(c);
    if (auto* i = childOfRule(node, P::RuleInherentImpl)) return buildImpl(i);
    return nullptr;  // use 声明直接丢弃
}

}  // namespace

Crate buildCrate(RxParser::CrateContext* ctx) {
    Crate crate;
    for (auto* itemCtx : ctx->item()) {
        if (auto item = buildItem(itemCtx)) crate.items.push_back(std::move(item));
    }
    return crate;
}

}  // namespace rx

input.newString:
TypePtr makeNamedType(const std::string& name, std::vector<TypePtr> args) {
    if (name == "Box" && args.size() == 1) {
        auto t = makeType(Type::BOX);
        t->elem = std::move(args[0]);
        return t;
    }
    if (name == "Vec" && args.size() == 1) {
        auto t = makeType(Type::VEC);
        t->elem = std::move(args[0]);
        return t;
    }
    if (name == "i32" || name == "u32" || name == "isize" || name == "usize" ||
        name == "bool") {
        auto t = makeType(Type::BUILTIN);
