#include "ast/ast.h"

#include <sstream>

namespace rx {
namespace {

void put(std::ostringstream& os, int indent, const std::string& s) {
    os << std::string(static_cast<size_t>(indent) * 2, ' ') << s << "\n";
}

std::string typeStr(const Type& t) {
    switch (t.kind) {
        case Type::BUILTIN:
        case Type::STRUCT:
            return t.name;
        case Type::UNIT:
            return "()";
        case Type::BOX:
            return "Box<" + (t.elem ? typeStr(*t.elem) : "?") + ">";
        case Type::VEC:
            return "Vec<" + (t.elem ? typeStr(*t.elem) : "?") + ">";
        case Type::REF:
            return (t.isMut ? "&mut " : "&") + (t.elem ? typeStr(*t.elem) : "?");
        case Type::ARRAY:
            return "[" + (t.elem ? typeStr(*t.elem) : "?") + "; " + t.arrayLen + "]";
    }
    return "?";
}

std::string constStr(const ConstVal& v) {
    if (v.kind == ConstVal::NEG) return "-(" + (v.inner ? constStr(*v.inner) : "?") + ")";
    return v.text;
}

void dumpExpr(std::ostringstream& os, const Expr& e, int indent);
void dumpBlock(std::ostringstream& os, const Block& b, int indent);

const char* exprName(Expr::Kind k) {
    switch (k) {
        case Expr::INT_LIT: return "IntLit";
        case Expr::BOOL_LIT: return "BoolLit";
        case Expr::PATH: return "Path";
        case Expr::UNIT: return "Unit";
        case Expr::UNARY: return "Unary";
        case Expr::BINARY: return "Binary";
        case Expr::ASSIGN: return "Assign";
        case Expr::CALL: return "Call";
        case Expr::METHOD_CALL: return "MethodCall";
        case Expr::FIELD: return "Field";
        case Expr::INDEX: return "Index";
        case Expr::ARRAY: return "Array";
        case Expr::REPEAT_ARRAY: return "RepeatArray";
        case Expr::STRUCT_INIT: return "StructInit";
        case Expr::CAST: return "Cast";
        case Expr::REF: return "Ref";
        case Expr::DEREF: return "Deref";
        case Expr::BLOCK: return "Block";
        case Expr::IF: return "If";
        case Expr::WHILE: return "While";
        case Expr::LOOP: return "Loop";
        case Expr::BREAK: return "Break";
        case Expr::CONTINUE: return "Continue";
        case Expr::RETURN: return "Return";
        case Expr::UNKNOWN: return "Unknown";
    }
    return "?";
}

void dumpPath(std::ostringstream& os, const std::vector<PathSegment>& path) {
    for (size_t i = 0; i < path.size(); ++i) {
        if (i) os << "::";
        os << path[i].name;
        if (!path[i].typeArgs.empty()) {
            os << "<";
            for (size_t j = 0; j < path[i].typeArgs.size(); ++j) {
                if (j) os << ", ";
                os << typeStr(*path[i].typeArgs[j]);
            }
            os << ">";
        }
    }
}

void dumpExpr(std::ostringstream& os, const Expr& e, int indent) {
    std::string head = exprName(e.kind);
    if (e.kind == Expr::PATH || e.kind == Expr::STRUCT_INIT) {
        std::ostringstream p;
        dumpPath(p, e.path);
        head += " " + p.str();
    } else if (e.kind == Expr::INT_LIT || e.kind == Expr::BOOL_LIT || e.kind == Expr::UNARY ||
               e.kind == Expr::BINARY || e.kind == Expr::ASSIGN || e.kind == Expr::METHOD_CALL ||
               e.kind == Expr::FIELD) {
        if (!e.op.empty()) head += " " + e.op;
    } else if (e.kind == Expr::CAST && e.type) {
        head += " as " + typeStr(*e.type);
    } else if (e.kind == Expr::REF && !e.op.empty()) {
        head += " " + e.op;
    }
    put(os, indent, head);

    if (e.kind == Expr::STRUCT_INIT) {
        for (auto& f : e.fields) {
            put(os, indent + 1, "Field " + f.name);
            if (f.value) dumpExpr(os, *f.value, indent + 2);
        }
    }
    for (auto& kid : e.kids)
        if (kid) dumpExpr(os, *kid, indent + 1);
    if (e.count) put(os, indent + 1, "count " + constStr(*e.count));
    if (e.block) dumpBlock(os, *e.block, indent + 1);
}

void dumpStmt(std::ostringstream& os, const Stmt& s, int indent) {
    if (s.kind == Stmt::LET) {
        std::string head = "Let " + std::string(s.isMut ? "mut " : "") + s.name;
        if (s.type) head += ": " + typeStr(*s.type);
        put(os, indent, head);
        if (s.expr) dumpExpr(os, *s.expr, indent + 1);
    } else {
        put(os, indent, "ExprStmt");
        if (s.expr) dumpExpr(os, *s.expr, indent + 1);
    }
}

void dumpBlock(std::ostringstream& os, const Block& b, int indent) {
    for (auto& s : b.stmts) dumpStmt(os, *s, indent);
    if (b.tail) {
        put(os, indent, "Tail");
        dumpExpr(os, *b.tail, indent + 1);
    }
}

void dumpItem(std::ostringstream& os, const Item& item, int indent) {
    switch (item.kind) {
        case Item::FN: {
            std::string head = "Fn " + item.fn.name + "(";
            for (size_t i = 0; i < item.fn.params.size(); ++i) {
                if (i) head += ", ";
                auto& p = item.fn.params[i];
                head += std::string(p.isMut ? "mut " : "") + p.name;
                if (p.type) head += ": " + typeStr(*p.type);
            }
            head += ")";
            if (item.fn.ret) head += " -> " + typeStr(*item.fn.ret);
            put(os, indent, head);
            if (item.fn.body) dumpBlock(os, *item.fn.body, indent + 1);
            break;
        }
        case Item::STRUCT: {
            put(os, indent, "Struct " + item.structDef.name +
                                (item.structDef.derives.empty() ? "" : " derive"));
            for (auto& d : item.structDef.derives) put(os, indent + 1, "derive " + d);
            for (auto& f : item.structDef.fields)
                put(os, indent + 1, "field " + f.name + ": " + (f.type ? typeStr(*f.type) : "?"));
            break;
        }
        case Item::CONST:
            put(os, indent, "Const " + item.constDef.name + ": " +
                                (item.constDef.type ? typeStr(*item.constDef.type) : "?") +
                                " = " + (item.constDef.value ? constStr(*item.constDef.value) : "?"));
            break;
        case Item::IMPL:
            put(os, indent, "Impl " + (item.impl.target ? typeStr(*item.impl.target) : "?"));
            for (auto& sub : item.impl.items)
                if (sub) dumpItem(os, *sub, indent + 1);
            break;
    }
}

}  // namespace

std::string dumpCrate(const Crate& crate) {
    std::ostringstream os;
    for (auto& item : crate.items)
        if (item) dumpItem(os, *item, 0);
    return os.str();
}

}  // namespace rx

