#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

#include "antlr4-runtime.h"
#include "RxLexer.h"
#include "RxParser.h"
#include "ast/ast.h"
#include "frontend/ast_builder.h"

using namespace antlr4;

// 只要词法/语法报错，就把 hasError 置 true
struct ErrorListener : public BaseErrorListener {
    bool hasError = false;
    void syntaxError(Recognizer* /*recognizer*/, Token* /*offending*/,
                     size_t line, size_t column, const std::string& message,
                     std::exception_ptr /*e*/) override {
        hasError = true;
        std::cerr << line << ":" << column << ": syntax error: " << message << "\n";
    }
};

int main(int argc, char** argv) {
    // 用法：rxcc --stage semantic [--dump-tree] [--dump-ast] <源文件>
    bool dumpTree = false;
    bool dumpAst = false;
    std::string stage;
    std::string sourcePath;
    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "--dump-tree") {
            dumpTree = true;
        } else if (arg == "--dump-ast") {
            dumpAst = true;
        } else if (arg == "--stage" && i + 1 < argc) {
            stage = argv[++i];
        } else {
            sourcePath = arg;
        }
    }
    if (stage != "semantic" || sourcePath.empty()) {
        std::cerr << "usage: rxcc --stage semantic [--dump-tree] [--dump-ast] <source.rx>\n";
        return 1;
    }

    std::ifstream in(sourcePath, std::ios::binary);
    if (!in) {
        std::cerr << "cannot open " << sourcePath << "\n";
        return 1;
    }
    std::stringstream buffer;
    buffer << in.rdbuf();

    try {
        ErrorListener listener;

        ANTLRInputStream input(buffer.str());
        RxLexer lexer(&input);
        lexer.removeErrorListeners();
        lexer.addErrorListener(&listener);

        CommonTokenStream tokens(&lexer);
        tokens.fill();

        RxParser parser(&tokens);
        parser.removeErrorListeners();
        parser.addErrorListener(&listener);

        RxParser::CrateContext* root = parser.crate();
        if (listener.hasError) {
            return 1;
        }
        if (dumpTree) {
            std::cout << root->toStringTree(&parser) << "\n";
        }
        if (dumpAst) {
            rx::Crate crate = rx::buildCrate(root);
            std::cout << rx::dumpCrate(crate);
        }

        // TODO：下一步在这里做语义检查，先直接接受
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "internal error: " << e.what() << "\n";
        return 1;
    } catch (...) {
        std::cerr << "internal error\n";
        return 1;
    }
}

