std::any ASTVisitor::visitItem(RxParser::ItemContext *ctx) {
    auto func = ctx->functionDefinition();
    auto stru = ctx->structDefinition();
    auto cons = ctx->constantItem();
    auto impl = ctx->inherentImpl();
    if (func) {
        return visit(func);
    }
    if (stru) {
        return visit(stru);
    }
    if (cons) {
        return visit(cons);
    }
    if (impl) {
        return visit(impl);
    }
    return static_cast<Item*>(nullptr);
}

