```cpp
std::any ASTVisitor::visitConstValue(RxParser::ConstValueContext* ctx) {
    if (auto* inner = ctx->constValue()) return visit(inner);   // ( constValue ) 剥括号
    auto* now = make<ConstValue>();
    if (ctx->INTEGER_LITERAL()) {
        now->kind_ = ConstValue::INT;
        now->text_ = ctx->INTEGER_LITERAL()->getText();         // 原文，含后缀/进制
    } else if (ctx->TRUE() || ctx->FALSE()) {
        now->kind_ = ConstValue::BOOL;
        now->text_ = ctx->TRUE() ? "true" : "false";
    } else if (auto* p = ctx->pathInExpression()) {
        now->kind_ = ConstValue::PATH;
        now->text_ = p->getText();                              // "N" / "Config::LIMIT" / "Self::LIMIT"
    } else if (auto* m = ctx->magnitude()) {                    // - magnitude
        now->kind_ = ConstValue::NEG;
        now->inner_ = anyConstValue(visit(m));
    }
    return static_cast<ConstValue*>(now);
}

std::any ASTVisitor::visitMagnitude(RxParser::MagnitudeContext* ctx) {
    if (auto* inner = ctx->magnitude()) return visit(inner);    // ( magnitude )
    auto* now = make<ConstValue>();
    if (ctx->INTEGER_LITERAL()) { now->kind_ = ConstValue::INT;  now->text_ = ctx->INTEGER_LITERAL()->getText(); }
    else if (auto* p = ctx->pathInExpression()) { now->kind_ = ConstValue::PATH; now->text_ = p->getText(); }
    return static_cast<ConstValue*>(now);
}
```

要点：`-1` → `NEG(INT "1")`，`-N` → `NEG(PATH "N")`；括号剥掉不建节点；整数存原文，数值求值留到 sema；PATH 如果以后 sema 要按段解析，把 `text_` 拆 `::` 或另存段表都行。文档 1.10 的 ConstVal 表下面也补了这段。

