 std::any ASTVisitor::visitReferenceType(RxParser::ReferenceTypeContext *ctx) {
     bool isMut = (ctx->MUT() != nullptr);
     Type* inner = anyType(visit(ctx->typeRef()));
     auto refMake = [&](bool isMut, Type* elem) {
         auto ref = make<Type>();
         ref->kind_ = Type::kTypeKind::REF;
         ref->isMut_ = isMut;
         ref->elem_ = elem;
         return ref;
