std::any ASTVisitor::visitCastExpression(RxParser::CastExpressionContext* ctx) {
    Expr* now = anyExpr(visit(ctx->unaryExpression()));
    for (auto* t : ctx->typeRef()) {          // AS 后有多个 typeRef，按序各转一次
        auto* cast = make<castExpr>();
        cast->operand_ = now;
        cast->target_  = anyType(visit(t));
        now = cast;
    }
    return static_cast<Expr*>(now);
}
```

`x as u32 as i32` 得到：

```
Cast i32
  Cast u32
    Path x
```

`closedCastExpression : unaryExpression | castExpression AS closedCastType` 是 `<` 消歧义用的变体：要么原样转发 `unary`，要么在已折好的链末尾再包一层，但目标类型是 `closedCastType`：

```cpp
std::any ASTVisitor::visitClosedCastExpression(RxParser::ClosedCastExpressionContext* ctx) {
    if (auto* u = ctx->unaryExpression()) return visit(u);        // 没有结尾 as
    Expr* now = anyExpr(visit(ctx->castExpression()));            // 前缀链
    auto* cast = make<castExpr>();
    cast->operand_ = now;
    cast->target_  = anyType(visit(ctx->closedCastType()));
    return static_cast<Expr*>(cast);
}
```

