std::any ASTVisitor::visitPostfixExpression(RxParser::PostfixExpressionContext* ctx) {
    Expr* now = anyExpr(visit(ctx->primaryExpression()));
    for (auto* suf : ctx->postfixSuffix()) {
        if (auto* args = suf->callArguments()) {
            auto* call = make<callExpr>();
            call->callee_ = now;
            for (auto* a : args->expression()) call->args_.push_back(anyExpr(visit(a)));
            now = call;
        } else if (auto* dot = suf->dotSuffix()) {
            if (auto* args = dot->callArguments()) {   // 方法调用
                auto* m = make<methodCallExpr>();
                m->recv_ = now;
                m->name_ = dot->pathExprSegment()->pathIdentSegment()->getText();
                for (auto* a : args->expression()) m->args_.push_back(anyExpr(visit(a)));
                now = m;
            } else {                                   // 字段
                auto* f = make<fieldExpr>();
                f->recv_ = now;
                f->name_ = dot->identifier()->getText();
                now = f;
            }
        } else {                                       // [expr]
            auto* idx = make<indexExpr>();
            idx->recv_ = now;
            idx->index_ = anyExpr(visit(suf->expression()));
            now = idx;
        }
    }
    return static_cast<Expr*>(now);
}
```

